const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

const body = $input.first().json.body || {};
const contactId = parseInt(body.contact_id, 10);
if (!Number.isInteger(contactId)) throw new Error('"contact_id" must be an integer.');

return [{ json: { requesterId: parseInt(match[1], 10), contactId } }];

const requester = $input.first().json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');

const contact = $('Look Up Contact').first().json;
if (!contact || !contact.phone) throw new Error('This contact has no phone number on file.');

const integration = $input.first().json;
if (!integration.api_key) throw new Error('Vapi is not connected — add an API key in Settings \u2192 Integrations.');

const config = integration.config || {};
if (!config.assistant_id || !config.phone_number_id) {
  throw new Error('Vapi is connected but missing Assistant ID / Phone Number ID \u2014 fill those in under Settings \u2192 Integrations.');
}

return [{
  json: {
    apiKey: integration.api_key,
    bodyJson: JSON.stringify({
      assistantId: config.assistant_id,
      phoneNumberId: config.phone_number_id,
      customer: {
        number: contact.phone,
        name: [contact.first_name, contact.last_name].filter(Boolean).join(' ') || undefined,
      },
    }),
  },
}];
